script:
// Qualitative cerebral autoregulation curve: CBF against MAP (0..200 mmHg).
// f(m) = 1 for L <= m <= U; m < L: max(0.12, 1 - ((L - m)/(L - 10))^1.15 * 0.88); m > U: 1 + 0.9*((m - U)/50)^1.4.
// Normal: L = 50, U = 150. Shifted curve = the same shape with L and U both raised by s: f(m - s).
const L0 = 50, U0 = 150, S_HTN = 40, S_TX = 15;
const X0 = 100, X1 = 584, YB = 460, YT = 164, VMAX = 2;   // plot box, CBF 0..2 (plateau = 1)
const sx = m => X0 + (X1 - X0) * m / 200;
const sy = v => YB - (YB - YT) * v / VMAX;
const TEAL = "#2a9d8f", TEAL_D = "#1d6f66", RED = "#c0392b", AMBER = "#d68a0c", AMBER_D = "#9a5d00";
const YP = sy(1);                                             // plateau height
function f(m) {
  if (m < L0) return Math.max(0.12, 1 - Math.pow((L0 - m) / (L0 - 10), 1.15) * 0.88);
  if (m > U0) return 1 + 0.9 * Math.pow((m - U0) / 50, 1.4);
  return 1;
}
function curve(s) {
  let d = "";
  for (let m = 0; m <= 200; m += 1) d += (m ? " L " : "M ") + sx(m).toFixed(1) + " " + sy(f(m - s)).toFixed(1);
  return d;
}
function arrowD(xa, xb, y, h) {                               // horizontal arrow, head at xb
  const dir = xb >= xa ? 1 : -1, hx = xb - dir * h;
  return "M " + xa.toFixed(1) + " " + y + " L " + hx.toFixed(1) + " " + y +
    " M " + hx.toFixed(1) + " " + (y - h * 0.62).toFixed(1) + " L " + xb.toFixed(1) + " " + y + " L " + hx.toFixed(1) + " " + (y + h * 0.62).toFixed(1);
}
let el = {};
function txt(api, parent, s, attrs) {
  const t = api.el("text", Object.assign({"font-family": "system-ui,sans-serif", "font-weight": 700, "font-size": 18,
    stroke: "#ffffff", "stroke-width": 5, "stroke-linejoin": "round", "paint-order": "stroke"}, attrs), parent);
  t.textContent = s; return t;
}
function setup(api) {
  const grid = api.$("#grid"), ticks = api.$("#ticks"), band = api.$("#band"), plot = api.$("#plot");
  for (let m = 0; m <= 200; m += 50) {
    if (m > 0) api.el("line", {x1: sx(m), y1: YB, x2: sx(m), y2: YT}, grid);
    api.el("line", {x1: sx(m), y1: YB, x2: sx(m), y2: YB + 7, stroke: "@ink", "stroke-width": 2.5}, ticks);
    const lim = m === L0 || m === U0;
    const t = api.el("text", {x: sx(m), y: YB + 27, "text-anchor": "middle", fill: lim ? TEAL_D : "@muted", "font-weight": lim ? 800 : 600}, ticks);
    t.textContent = String(m);
  }
  // Normal autoregulation range: light band, dashed guides from the limits down to the axis.
  el.band = api.el("g", {}, band);
  api.el("rect", {x: sx(L0), y: YT, width: sx(U0) - sx(L0), height: YB - YT, fill: TEAL, "fill-opacity": 0.09}, el.band);
  [L0, U0].forEach(m => api.el("line", {x1: sx(m), y1: YB, x2: sx(m), y2: YP, stroke: TEAL, "stroke-width": 2.5, "stroke-dasharray": "6 6"}, el.band));
  el.autoLabel = txt(api, plot, "autoregulation", {x: sx(100), y: YP - 16, "text-anchor": "middle", fill: TEAL_D});
  // Curves: faint hypertensive ghost (beat 3), normal (teal), moving copy (red solid / amber dashed).
  el.ghost = api.el("path", {d: curve(S_HTN), fill: "none", stroke: RED, "stroke-width": 3.5, "stroke-linecap": "round", "stroke-linejoin": "round"}, plot);
  el.normal = api.el("path", {d: curve(0), fill: "none", stroke: TEAL, "stroke-width": 6, "stroke-linecap": "round", "stroke-linejoin": "round", pathLength: 1}, plot);
  el.red = api.el("path", {fill: "none", stroke: RED, "stroke-width": 6, "stroke-linecap": "round", "stroke-linejoin": "round"}, plot);
  el.amber = api.el("path", {fill: "none", stroke: AMBER, "stroke-width": 5, "stroke-linecap": "round", "stroke-linejoin": "round", "stroke-dasharray": "12 9"}, plot);
  // Beat 2: red right-arrow over the plateau + label.
  el.redArrow = api.el("path", {fill: "none", stroke: RED, "stroke-width": 5, "stroke-linecap": "round", "stroke-linejoin": "round"}, plot);
  el.redLabel = txt(api, plot, "chronic hypertension", {x: sx(120), y: YP - 84, "text-anchor": "middle", fill: RED});
  // Beat 3: small amber left-arrow + label.
  el.amberArrow = api.el("path", {fill: "none", stroke: AMBER, "stroke-width": 5, "stroke-linecap": "round", "stroke-linejoin": "round"}, plot);
  el.amberLabel = txt(api, plot, "treated, with time", {x: sx(115), y: YP + 56, "text-anchor": "middle", fill: AMBER_D});
}
function fade(api, node, k) { api.set(node, {opacity: k, display: k > 0.001 ? "inline" : "none"}); }
function render(t, api) {
  // Beat 1 (0-2700): range band + label fade in, normal curve draws on.
  fade(api, el.band, api.seg(t, 250, 900, "ease_out"));
  fade(api, el.autoLabel, api.seg(t, 300, 1000, "ease_out"));
  const draw = api.seg(t, 200, 2200, "ease_in_out");
  const thin = api.seg(t, 2800, 3400, "ease_in_out");
  api.set(el.normal, {"stroke-dasharray": draw.toFixed(4) + " 1.001", "stroke-opacity": draw > 0 ? 1 : 0,
    "stroke-width": 6 - 2.5 * thin, opacity: 1 - 0.4 * thin});
  // Beat 2 (2700-5000): red copy slides right, s 0 -> 40.
  const k2 = api.seg(t, 2800, 4300, "ease_in_out");
  const k3 = api.seg(t, 5100, 6400, "ease_in_out");          // beat 3: back part-way, s 40 -> 15
  const s = S_HTN * k2 - (S_HTN - S_TX) * k3;
  const swap = api.seg(t, 5100, 5600, "ease_in_out");         // red solid -> amber dashed
  const d = curve(s);
  api.set(el.red, {d: d}); fade(api, el.red, api.seg(t, 2800, 3000) * (1 - swap));
  api.set(el.amber, {d: d}); fade(api, el.amber, swap);
  fade(api, el.ghost, 0.4 * api.seg(t, 5100, 5500, "ease_out"));
  const ra = api.seg(t, 2800, 3000);
  api.set(el.redArrow, {d: arrowD(sx(100), sx(100) + Math.max(14, sx(S_HTN * k2) - sx(0)), YP - 46, 14)});
  fade(api, el.redArrow, ra * (1 - 0.3 * swap));
  fade(api, el.redLabel, api.seg(t, 2900, 3500, "ease_out") * (1 - 0.3 * swap));
  // Beat 3 (5000-8000): small amber left-arrow + label; hold from 6400.
  const xa = sx(115 + (S_HTN - S_TX) / 2), xb = xa - (sx(S_HTN - S_TX) - sx(0)) * k3;   // 25 mmHg long, centred over its label
  api.set(el.amberArrow, {d: arrowD(xa, Math.min(xa - 14, xb), YP + 26, 12)});
  fade(api, el.amberArrow, api.seg(t, 5100, 5300));
  fade(api, el.amberLabel, api.seg(t, 5200, 5800, "ease_out"));
}
